// Каталог собирается на лету: подарок = коллекция + модель + фон, номер вида "c12.5.33".
// Старые номера g0…g8176 переводятся через таблицу legacy, коллекции игроков не меняются.
(() => {
  const D = window.GIFT_DATA, enc = encodeURIComponent, CDN = "https://cdn.changes.tg/gifts";
  const cols = D.cols, bds = D.bds;
  const floors = cols.map((c) => c[1]);                  // минимальная цена коллекции в звёздах
  const baseFloors = Object.fromEntries(cols.map((c) => [c[0], c[1]]));
  // множитель редкости: модель и фон. Самый частый = ×1, редкие дороже, общий множитель не больше ×15
  const MM = cols.map((c) => { const mx = Math.max(...c[2].map((m) => m[1])); return c[2].map((m) => Math.pow(mx / Math.max(1, m[1]), 0.7)); });
  const BM = cols.map((c) => { const mx = Math.max(...c[3].map((b) => b[1])); return c[3].map((b) => Math.pow(mx / Math.max(1, b[1]), 0.5) * (/^(Black|Onyx Black)$/.test(bds[b[0]][0]) ? 1.35 : 1)); });
  const base = []; let N = 0;
  cols.forEach((c, i) => { base[i] = N; N += c[2].length * c[3].length; });
  const mult = (ci, mi, li) => Math.min(15, MM[ci][mi] * BM[ci][li]);
  const priceOf = (ci, mi, li) => Math.max(1, Math.round(floors[ci] * mult(ci, mi, li)));
  const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };

  function parse(id) {
    if (typeof id !== "string") return null;
    if (id[0] === "g") { const l = D.legacy[+id.slice(1)]; return l ? parse(l) : null; }
    const m = /^c(\d+)\.(\d+)\.(\d+)$/.exec(id);
    if (!m) return null;
    const ci = +m[1], mi = +m[2], li = +m[3], c = cols[ci];
    return c && c[2][mi] && c[3][li] ? [ci, mi, li] : null;
  }
  const cache = new Map();
  function get(id) {
    let g = cache.get(id);
    if (g) return g;
    const p = parse(id);
    if (!p) return undefined;
    const [ci, mi, li] = p, c = cols[ci], m = c[2][mi], b = bds[c[3][li][0]];
    const symbol = c[4][hash(id[0] === "g" ? D.legacy[+id.slice(1)] : id) % c[4].length];
    g = { id, gift: c[0], model: m[0], backdrop: b[0], symbol, ci, mi, li,
      rare: m[1] / 10, brare: c[3][li][1] / 10, srare: null, mult: mult(ci, mi, li), price: priceOf(ci, mi, li),
      c1: b[1], c2: b[2], cp: b[3], ct: b[4],
      img: `${CDN}/models/${enc(c[0])}/png/${enc(m[0])}.png`, anim: `${CDN}/models/${enc(c[0])}/lottie/${enc(m[0])}.json`,
      sym: `${CDN}/patterns/${enc(c[0])}/png/${enc(symbol)}.png` };
    cache.set(id, g);
    return g;
  }
  const idOf = (k) => {                                    // порядковый номер сочетания -> номер подарка
    let lo = 0, hi = cols.length - 1;
    while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (base[mid] <= k) lo = mid; else hi = mid - 1; }
    const nb = cols[lo][3].length, r = k - base[lo];
    return `c${lo}.${Math.floor(r / nb)}.${r % nb}`;
  };

  // все подарки по цене: цена и номер упакованы в одно число, сортирует сам браузер (быстро даже для 500 тысяч)
  let keys = null;
  const SH = 1e6;
  function sorted() {
    if (keys) return keys;
    keys = new Float64Array(N);
    let k = 0;
    cols.forEach((c, ci) => { for (let mi = 0; mi < c[2].length; mi++) for (let li = 0; li < c[3].length; li++, k++) keys[k] = priceOf(ci, mi, li) * SH + k; });
    keys.sort();
    return keys;
  }
  const keyPrice = (x) => Math.floor(x / SH), keyIdx = (x) => x % SH;
  // самый дорогой подарок не дороже суммы
  function best(value) {
    const K = sorted(); let lo = 0, hi = K.length - 1, ans = -1;
    while (lo <= hi) { const mid = (lo + hi) >> 1; if (keyPrice(K[mid]) <= value) { ans = mid; lo = mid + 1; } else hi = mid - 1; }
    return ans < 0 ? null : get(idOf(keyIdx(K[ans])));
  }
  // подарок дороже min, ближайший по цене к want
  function near(want, min) {
    const K = sorted(); let lo = 0, hi = K.length - 1;
    while (lo < hi) { const mid = (lo + hi) >> 1; if (keyPrice(K[mid]) < want) lo = mid + 1; else hi = mid; }
    for (let d = 0; d < K.length; d++) {
      for (const i of [lo + d, lo - d - 1]) if (i >= 0 && i < K.length && keyPrice(K[i]) > min) return get(idOf(keyIdx(K[i])));
    }
    return null;
  }
  // поиск: цена от lo до hi, слова ищутся в названии, модели и фоне
  function search({ q = "", lo = 0, hi = Infinity, dir = 1, limit = 120 } = {}) {
    const K = sorted(), words = q.toLowerCase().split(/\s+/).filter(Boolean), out = [];
    let total = 0;
    const colOk = words.map((w) => cols.map((c) => c[0].toLowerCase().includes(w)));
    const modOk = words.map((w) => cols.map((c) => c[2].map((m) => m[0].toLowerCase().includes(w))));
    const bdOk = words.map((w) => bds.map((b) => b[0].toLowerCase().includes(w)));
    const start = dir > 0 ? 0 : K.length - 1, step = dir > 0 ? 1 : -1;
    for (let i = start; i >= 0 && i < K.length; i += step) {
      const p = keyPrice(K[i]);
      if (p < lo || p >= hi) continue;
      if (words.length) {
        const id = idOf(keyIdx(K[i])), [ci, mi, li] = parse(id), gi = cols[ci][3][li][0];
        if (!words.every((w, j) => colOk[j][ci] || modOk[j][ci][mi] || bdOk[j][gi])) continue;
        total++; if (out.length < limit) out.push(get(id));
      } else { total++; if (out.length < limit) out.push(get(idOf(keyIdx(K[i])))); }
    }
    return { items: out, total };
  }
  function setFloors(f) {
    cols.forEach((c, i) => { floors[i] = (f && f[c[0]] > 0) ? f[c[0]] : c[1]; });
    keys = null;
    for (const g of cache.values()) g.price = priceOf(g.ci, g.mi, g.li);
  }
  // самый дорогой подарок каждой коллекции (для особого стиля и подборок)
  const topOf = (ci) => { let bm = 0, bl = 0; cols[ci][2].forEach((_, mi) => cols[ci][3].forEach((__, li) => { if (mult(ci, mi, li) > mult(ci, bm, bl)) { bm = mi; bl = li; } })); return get(`c${ci}.${bm}.${bl}`); };
  window.Cat = { get, parse, best, near, search, setFloors, topOf, sorted, count: N, cols, bds, baseFloors,
    idAt: (k) => idOf(k), colByName: Object.fromEntries(cols.map((c, i) => [c[0], i])) };
  window.GIFT_FLOORS = baseFloors;
})();
